namespace XV2SaveEditor;

public static class FestivalPresetAccess
{
    public const int UnlockOffset = 0xDF2C0;
    public const int UnlockLength = 0x70;
    private const int PartnerOffset = 757220;
    private const int PartnerStride = 19588;
    private const int PartnerCount = 54;
    private const int PartnerSize = 44;

    // Verified against a matched locked/all-Festival pair from the current save revision.
    // Missing records are initialized from this canonical block; existing records are preserved.
    private static readonly byte[] PartnerTemplate = Convert.FromBase64String(
        "");

    public static (int RecordsInitialized, int FlagsChanged) UnlockAll(byte[] data) => Unlock(data, Enumerable.Range(0, 8));

    public static (int RecordsInitialized, int FlagsChanged) Unlock(byte[] data, IEnumerable<int> characterSlots)
    {
        Validate(data, UnlockOffset, UnlockLength);
        int records = 0;
        foreach (int slot in characterSlots.Distinct())
        {
            if (slot is < 0 or >= 8) throw new ArgumentOutOfRangeException(nameof(characterSlots));
            int block = PartnerOffset + slot * PartnerStride;
            Validate(data, block, PartnerTemplate.Length);
            for (int index = 0; index < PartnerCount; index++)
            {
                int source = index * PartnerSize;
                int target = block + source;
                ushort templateId = BitConverter.ToUInt16(PartnerTemplate, source);
                ushort currentId = BitConverter.ToUInt16(data, target);
                if (templateId is 0 or ushort.MaxValue || currentId is not (0 or ushort.MaxValue)) continue;
                Array.Copy(PartnerTemplate, source, data, target, PartnerSize);
                records++;
            }
        }

        int flags = 0;
        for (int i = 0; i < UnlockLength; i++)
        {
            byte value = (byte)(data[UnlockOffset + i] | 0x07);
            if (value != data[UnlockOffset + i]) flags++;
            data[UnlockOffset + i] = value;
        }
        return (records, flags);
    }

    private static void Validate(byte[] data, int offset, int length)
    {
        if (offset < 0 || offset + length > data.Length)
            throw new InvalidOperationException("The verified Festival preset structure is outside this save revision.");
    }
}
